// Session-only interaction study. No storage, vault access, network requests or AI calls.
const $ = s => document.querySelector(s);
const kinds = {script:'剧本', person:'人物', scene:'场景', shot:'镜头', frame:'关键帧', video:'视频', image:'图片'};
const example = [
  {id:'story',kind:'script',title:'雨夜归家',body:'她拎着晚餐走入楼道，掏出钥匙。\n门锁响起，屋内的人从书中抬头。\n她推门进来，把晚餐放在桌上。',x:0,y:110},
  {id:'person',kind:'person',title:'归家的人',body:'人物照片放在这里。\n把这张卡连接到需要保持人物一致的镜头。',x:320,y:10},
  {id:'room',kind:'scene',title:'玄关与餐桌',body:'先确认门、过道和餐桌的位置。',x:320,y:285},
  {id:'shot1',kind:'shot',title:'01 · 门锁转动',body:'钥匙插入锁孔，轻轻转动。\n先听见门锁声，再切到屋内反应。',intent:'用门锁这个细节交代“有人到家”，并以声音引出下一个镜头。',framing:'特写 · 固定机位',x:670,y:100},
  {id:'frame',kind:'frame',title:'钥匙刚接触锁孔',body:'起始状态：钥匙尚未转动。\n这张卡负责镜头开始时的构图。',x:670,y:355},
  {id:'video',kind:'video',title:'门锁转动 · 候选 01',body:'生成的视频放在这里。\n当前是占位示例，可拖入视频体验预览。',decision:'待选择',x:1010,y:100},
  {id:'shot2',kind:'shot',title:'02 · 从书中抬头',body:'屋内的人听见开门声，抬眼看向玄关。',intent:'让观众读到人物听见声音后的反应。',framing:'近景 · 固定机位',x:1010,y:415}
];
const exampleLinks = [{from:'story',to:'shot1',label:'剧情拆分'},{from:'person',to:'shot1',label:'人物参考'},{from:'room',to:'shot2',label:'场景参考'},{from:'frame',to:'shot1',label:'起始帧'},{from:'video',to:'shot1',label:'视频候选'}];
let nodes=[], links=[], selected=null, source=null, view={x:50,y:50,k:1}, drag=null;
let urls=[];
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const say = text => $('#status').textContent=text;
function state(n){if(n.kind==='shot'){const candidates=links.filter(l=>l.to===n.id&&l.label==='视频候选').map(l=>nodes.find(v=>v.id===l.from)).filter(Boolean);if(candidates.some(v=>v.decision==='已采用'))return '已采用 · 可以进入剪辑';if(candidates.length&&candidates.every(v=>v.decision==='待重做'))return '待重做 · 候选需要重做';if(candidates.length)return '待选片 · 比较视频候选';if(!links.some(l=>l.to===n.id&&l.label==='起始帧'))return '待准备 · 缺少起始帧';return '待生成 · 参考已连接';}if(n.kind==='video')return n.decision||'待选择';if(n.kind==='frame')return '参考用途由连线指定';return '自由整理 · 点击编辑';}
function drawing(n){if(n.url&&n.kind!=='video')return `<img alt="${esc(n.title)}" src="${esc(n.url)}" draggable="false">`;if(n.kind==='scene')return '<svg viewBox="0 0 210 88" aria-label="平面示意"><path d="M15 10H195V78H15V10M75 10V45M75 65V78M135 10V38"/><path d="M75 45Q95 45 95 65H75"/><rect x="125" y="48" width="40" height="20"/><text x="26" y="33">玄关</text><text x="125" y="42">餐桌</text><text x="140" y="74">平面示意</text></svg>';if(n.kind==='frame')return '<svg viewBox="0 0 210 88" aria-label="构图示意"><rect x="6" y="6" width="198" height="74"/><path d="M150 6V80M158 35H179M164 35V51M80 46H153"/><circle cx="70" cy="46" r="10"/><text x="16" y="71">构图示意 · 非生成图</text></svg>';if(n.kind==='video')return `<div class="symbol">▷ <span>${n.url?'已放入视频 · 点击播放':'视频占位 · 等待生成结果'}</span></div>`;return '';}
function render(){
  $('#nodes').innerHTML=nodes.map(n=>`<article class="node ${selected===n.id?'selected':''}" tabindex="0" role="button" aria-label="${esc(kinds[n.kind]+'：'+n.title)}" data-id="${n.id}" style="left:${n.x}px;top:${n.y}px"><div class="kind">${kinds[n.kind]}</div><h2>${esc(n.title)}</h2>${drawing(n)}<p>${esc(n.body)}</p><div class="state">${esc(state(n))}</div><button class="port" data-port="${n.id}" aria-label="从${esc(n.title)}连接" title="连接到另一张卡"></button></article>`).join('');
  $('#welcome').hidden=nodes.length>0; transform(); drawEdges();
}
function transform(){$('#world').style.transform=`translate(${view.x}px,${view.y}px) scale(${view.k})`;$('#zoom').textContent=Math.round(view.k*100)+'%';}
function drawEdges(){ $('#edges').innerHTML=links.map(l=>{const a=nodes.find(n=>n.id===l.from),b=nodes.find(n=>n.id===l.to);if(!a||!b)return '';const right=b.x>=a.x;const x1=a.x+(right?250:0),x2=b.x+(right?0:250),y1=a.y+95,y2=b.y+95;const bend=Math.max(70,Math.abs(x2-x1)*.5)*(right?1:-1);return `<g class="edge"><path d="M${x1} ${y1} C${x1+bend} ${y1},${x2-bend} ${y2},${x2} ${y2}"/><text x="${(x1+x2)/2}" y="${(y1+y2)/2-8}" text-anchor="middle">${esc(l.label)} →</text></g>`;}).join(''); }
function fit(){if($('#canvas').clientWidth<650&&nodes.length){view={x:24-nodes[0].x*.9,y:40-nodes[0].y*.9,k:.9};transform();return;}if(!nodes.length){view={x:50,y:50,k:1};transform();return;}const r=$('#canvas').getBoundingClientRect(),minX=Math.min(...nodes.map(n=>n.x)),minY=Math.min(...nodes.map(n=>n.y));const w=Math.max(...nodes.map(n=>n.x+250))-minX,h=Math.max(...nodes.map(n=>n.y+260))-minY;const k=Math.min(1,(r.width-100)/w,(r.height-90)/h);view={x:(r.width-w*k)/2-minX*k,y:30-minY*k,k:Math.max(.2,k)};transform();}
function inspect(id){selected=id;$('#tasks').hidden=true;$('#todo').setAttribute('aria-expanded','false');const n=nodes.find(n=>n.id===id);render();const panel=$('#inspector');panel.hidden=!n;if(!n)return;panel.innerHTML=`<header><h2>${kinds[n.kind]}详情</h2><button id="close" aria-label="关闭详情">×</button></header><label for="title">名称</label><input id="title" value="${esc(n.title)}"><label for="body">${n.kind==='script'?'在这里粘贴剧本':'内容'}</label><textarea id="body">${esc(n.body)}</textarea>${n.url?(n.kind==='video'?`<video controls src="${esc(n.url)}"></video>`:`<img src="${esc(n.url)}" alt="${esc(n.title)}">`):''}${n.kind==='shot'?`<div class="tip"><b>为什么这样拍</b><p>${esc(n.intent||'待讨论：这个镜头要让观众知道什么？')}</p><p>${esc(n.framing||'景别和机位待确定')}</p><small>示例分析；原型没有 AI 拆镜能力。</small></div>`:''}${n.kind==='video'?'<button id="adopt" class="primary">采用这个版本（演示）</button><button id="reject">需要重做（演示）</button>':''}<h3>这张卡与谁有关</h3><div id="relations"></div><button id="startlink">＋ 连接到另一张卡</button><p>编辑只在本次预览中保留。正式版由 Obsidian 保存。</p>`;
  $('#close').onclick=()=>{panel.hidden=true;selected=null;render();};
  for(const field of ['title','body'])$('#'+field).oninput=e=>{n[field]=e.target.value;render();say('已更新预览；刷新后恢复示例。');};
  $('#startlink').onclick=()=>startLink(n.id);
  if(n.kind==='video'){ $('#adopt').onclick=()=>decide(n,'已采用');$('#reject').onclick=()=>decide(n,'待重做'); }
  const related=links.filter(l=>l.from===id||l.to===id);$('#relations').innerHTML=related.length?related.map(l=>{const target=l.from===id?l.to:l.from;return `<div class="relation"><button data-focus="${target}">${esc(l.label)} ${l.from===id?'→':'←'} ${esc(nodes.find(n=>n.id===target)?.title)}</button><button data-remove="${links.indexOf(l)}" aria-label="移除${esc(l.label)}关系">移除</button></div>`;}).join(''):'<p>还没有连线。连接可说明素材给哪个镜头使用。</p>';
  panel.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>focusNode(b.dataset.focus));panel.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{links.splice(Number(b.dataset.remove),1);inspect(id);say('已移除连线，卡片和素材仍然保留。');});
}
function decide(n,value){const targets=links.filter(l=>l.from===n.id&&l.label==='视频候选').map(l=>l.to);if(!targets.length){say('先将视频连接到镜头，关系选择「视频候选」。');return;}if(value==='已采用')for(const l of links)if(targets.includes(l.to)&&l.label==='视频候选'&&l.from!==n.id){const other=nodes.find(v=>v.id===l.from);if(other?.decision==='已采用')other.decision='待选择';}n.decision=value;render();say(`预览中已标记「${value}」；未修改正式资料库。`);}
function startLink(id){source=id;$('#inspector').hidden=true;$('#connectbar').hidden=false;const n=nodes.find(n=>n.id===id);$('#connecttext').textContent=`从「${n.title}」连接：请点击目标卡片`;$('#relation').value=({script:'剧情拆分',person:'人物参考',scene:'场景参考',frame:'起始帧',video:'视频候选'})[n.kind]||'参考';say('选择用途后，点击要连接的卡片。Esc 取消。');}
function cancelLink(){source=null;$('#connectbar').hidden=true;}
function choose(id){if(source){if(id===source){say('请选择另一张卡片。');return;}const label=$('#relation').value;const sourceKind=nodes.find(n=>n.id===source)?.kind;if(label==='视频候选'&&sourceKind!=='video'){say('视频候选关系需要从视频卡发起。');return;}if(label==='起始帧'&&!['frame','image'].includes(sourceKind)){say('起始帧关系需要从关键帧或图片卡发起。');return;}if(['视频候选','起始帧','人物参考','场景参考','剧情拆分'].includes(label)&&nodes.find(n=>n.id===id)?.kind!=='shot'){say('这个用途需要连接到镜头卡；普通整理可选择「参考」。');return;}if(!links.some(l=>l.from===source&&l.to===id&&l.label===label))links.push({from:source,to:id,label});cancelLink();render();say(`已添加「${label}」关系。点击卡片可查看或移除连线。`);}else inspect(id);}
function focusNode(id){const n=nodes.find(n=>n.id===id);if(!n)return;const r=$('#canvas').getBoundingClientRect();view={x:Math.max(30,(r.width-350)/2-125)-n.x,y:Math.max(30,r.height/2-130)-n.y,k:1};inspect(id);}
function add(kind,extra={}){const r=$('#canvas').getBoundingClientRect();const n={id:crypto.randomUUID(),kind,title:'新'+kinds[kind],body:'',x:(r.width*.4-view.x)/view.k,y:(r.height*.3-view.y)/view.k,...extra};nodes.push(n);inspect(n.id);say(`已放入${kinds[kind]}卡。可以填写内容、拖动位置或连接用途。`);return n;}
function reset(demo){urls.forEach(u=>URL.revokeObjectURL(u));urls=[];nodes=demo?structuredClone(example):[];links=demo?structuredClone(exampleLinks):[];selected=null;cancelLink();$('#inspector').hidden=true;$('#tasks').hidden=true;$('#todo').setAttribute('aria-expanded','false');render();fit();say(demo?'先点「门锁转动」镜头，看清它需要什么，再试着拖动和连接卡片。':'从左上角添加剧本，或直接把文件拖到空白画布。');}
document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(b.dataset.add));$('#empty').onclick=()=>reset(false);$('#example').onclick=()=>reset(true);$('#theme').onclick=()=>document.body.classList.toggle('light');$('#fit').onclick=fit;$('#cancel').onclick=cancelLink;
function zoom(factor,x,y){const k=Math.max(.2,Math.min(2,view.k*factor));view={x:x-(x-view.x)*k/view.k,y:y-(y-view.y)*k/view.k,k};transform();}
$('#zoom-in').onclick=()=>zoom(1.15,$('#canvas').clientWidth/2,$('#canvas').clientHeight/2);$('#zoom-out').onclick=()=>zoom(1/1.15,$('#canvas').clientWidth/2,$('#canvas').clientHeight/2);
$('#canvas').addEventListener('wheel',e=>{e.preventDefault();const r=e.currentTarget.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.001),e.clientX-r.left,e.clientY-r.top);},{passive:false});
$('#canvas').onpointerdown=e=>{if(e.button!==0||e.target.closest('.canvas-bottom, #welcome'))return;const port=e.target.closest('[data-port]');if(port){startLink(port.dataset.port);return;}const el=e.target.closest('[data-id]');if(source&&el){choose(el.dataset.id);return;}e.preventDefault();const n=el&&nodes.find(n=>n.id===el.dataset.id);drag={id:e.pointerId,startX:e.clientX,startY:e.clientY,n,x:n?n.x:view.x,y:n?n.y:view.y,moved:false};e.currentTarget.setPointerCapture(e.pointerId);};
$('#canvas').onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(Math.hypot(dx,dy)>4)drag.moved=true;if(!drag.moved)return;if(drag.n){drag.n.x=drag.x+dx/view.k;drag.n.y=drag.y+dy/view.k;render();}else{view.x=drag.x+dx;view.y=drag.y+dy;transform();}};
$('#canvas').onpointerup=e=>{if(!drag||drag.id!==e.pointerId)return;const d=drag;drag=null;if(e.currentTarget.hasPointerCapture(e.pointerId))e.currentTarget.releasePointerCapture(e.pointerId);if(!d.moved){if(d.n)choose(d.n.id);else{$('#inspector').hidden=true;selected=null;render();}}};$('#canvas').onpointercancel=()=>drag=null;$('#canvas').onlostpointercapture=()=>drag=null;
$('#nodes').onclick=e=>{if(e.detail!==0)return;const port=e.target.closest('[data-port]');if(port)startLink(port.dataset.port);};
$('#nodes').onkeydown=e=>{if(e.target.closest('.port'))return;const el=e.target.closest('[data-id]');if(el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();choose(el.dataset.id);}};document.onkeydown=e=>{if(e.key==='Escape'){cancelLink();$('#inspector').hidden=true;$('#tasks').hidden=true;$('#todo').setAttribute('aria-expanded','false');selected=null;render();}};
function importFiles(files,point){let index=0;for(const file of files){const kind=file.type.startsWith('video/')?'video':file.type.startsWith('image/')?'image':null;if(!kind){say('此预览只接收图片和视频；剧本文字请粘贴到剧本卡。');continue;}const url=URL.createObjectURL(file);urls.push(url);add(kind,{title:file.name,body:'本次预览中的本地文件，未上传或复制。',url,...(point?{x:point.x+(index%3)*280,y:point.y+Math.floor(index/3)*270}:{} )});index++;}}
$('#import').onclick=()=>$('#files').click();$('#files').onchange=e=>{importFiles(e.target.files);e.target.value='';};$('#canvas').ondragover=e=>e.preventDefault();$('#canvas').ondrop=e=>{e.preventDefault();const r=e.currentTarget.getBoundingClientRect();importFiles(e.dataTransfer.files,{x:(e.clientX-r.left-view.x)/view.k,y:(e.clientY-r.top-view.y)/view.k});};
$('#todo').onclick=()=>{const panel=$('#tasks');panel.hidden=!panel.hidden;$('#todo').setAttribute('aria-expanded',String(!panel.hidden));$('#inspector').hidden=true;panel.innerHTML='<header><h2>下一步做什么</h2><button id="closetasks" aria-label="关闭待办">×</button></header><p>点击一项，直接找到对应镜头。</p>'+nodes.filter(n=>n.kind==='shot').map(n=>`<button class="task" data-task="${n.id}">${esc(n.title)}<span>${esc(state(n))}</span></button>`).join('');if(!nodes.some(n=>n.kind==='shot'))panel.innerHTML+='<p>目前没有镜头。可以先整理剧本和素材，不必急着拆镜头。</p>';$('#closetasks').onclick=()=>{panel.hidden=true;$('#todo').setAttribute('aria-expanded','false');};panel.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>focusNode(b.dataset.task));};
window.addEventListener('resize',fit);window.addEventListener('beforeunload',()=>urls.forEach(u=>URL.revokeObjectURL(u)));reset(true);
